import sys
def build_graph(k):
    n = 2
    while 2 ** (n - 2) < k:
        n += 1
    graph = [['N'] * n for _ in range(n)]
    for i in range(1, n):
        graph[0][i] = 'Y'
        graph[i][0] = 'Y'
    for i in range(1, n):
        for j in range(i + 1, n):
            if k & (1 << (j - 2)):
                graph[i][j] = 'Y'
                graph[j][i] = 'Y'
    return n, graph

k = int(sys.stdin.read().strip())
n, graph = build_graph(k)
print(n)
for row in graph:
    print(''.join(row))
